import sys
import io
import base64
import tkinter as tk
import tkinter.font as tkfont
import ctypes
from ctypes import wintypes
from PIL import Image, ImageTk

MUTEX_NAME = "ArrowKeysVirtualKeyboard_SingleInstance_9F3C1A"

_mutex = ctypes.windll.kernel32.CreateMutexW(None, False, MUTEX_NAME)
if ctypes.windll.kernel32.GetLastError() == 183:
    ctypes.windll.user32.MessageBoxW(
        0,
        "ArrowKeys is already running.\n\nYou can use the window already open on your screen.",
        "ArrowKeys",
        0x30 | 0x40000,
    )
    sys.exit(0)

PUL = ctypes.POINTER(ctypes.c_ulong)
KEYEVENTF_KEYUP = 0x0002
KEYEVENTF_SCANCODE = 0x0008
KEYEVENTF_EXTENDEDKEY = 0x0001

SCANCODES = {"up": 0x48, "down": 0x50, "left": 0x4B, "right": 0x4D}


class KEYBDINPUT(ctypes.Structure):
    _fields_ = [
        ("wVk", wintypes.WORD), ("wScan", wintypes.WORD),
        ("dwFlags", wintypes.DWORD), ("time", wintypes.DWORD),
        ("dwExtraInfo", PUL),
    ]


class HARDWAREINPUT(ctypes.Structure):
    _fields_ = [("uMsg", wintypes.DWORD), ("wParamL", wintypes.WORD), ("wParamH", wintypes.WORD)]


class MOUSEINPUT(ctypes.Structure):
    _fields_ = [
        ("dx", wintypes.LONG), ("dy", wintypes.LONG), ("mouseData", wintypes.DWORD),
        ("dwFlags", wintypes.DWORD), ("time", wintypes.DWORD), ("dwExtraInfo", PUL),
    ]


class INPUT_UNION(ctypes.Union):
    _fields_ = [("ki", KEYBDINPUT), ("mi", MOUSEINPUT), ("hi", HARDWAREINPUT)]


class INPUT(ctypes.Structure):
    _fields_ = [("type", wintypes.DWORD), ("union", INPUT_UNION)]


def send_key(direction, key_up=False):
    flags = KEYEVENTF_SCANCODE | KEYEVENTF_EXTENDEDKEY
    if key_up:
        flags |= KEYEVENTF_KEYUP
    extra = ctypes.c_ulong(0)
    ii = INPUT_UNION()
    ii.ki = KEYBDINPUT(0, SCANCODES[direction], flags, 0, ctypes.pointer(extra))
    inp = INPUT(1, ii)
    ctypes.windll.user32.SendInput(1, ctypes.pointer(inp), ctypes.sizeof(inp))


user32 = ctypes.windll.user32
gdi32 = ctypes.windll.gdi32
dwmapi = ctypes.windll.dwmapi

GWL_EXSTYLE = -20
WS_EX_NOACTIVATE = 0x08000000
WS_EX_TOOLWINDOW = 0x00000080
SWP_NOMOVE = 0x0002
SWP_NOSIZE = 0x0001
SWP_NOACTIVATE = 0x0010
HWND_TOPMOST = -1
RGN_OR = 2
DWMWA_NCRENDERING_POLICY = 2
DWMNCRP_DISABLED = 1


def disable_shadow(hwnd):
    value = ctypes.c_int(DWMNCRP_DISABLED)
    dwmapi.DwmSetWindowAttribute(hwnd, DWMWA_NCRENDERING_POLICY, ctypes.byref(value), ctypes.sizeof(value))


def apply_noactivate(hwnd):
    style = user32.GetWindowLongW(hwnd, GWL_EXSTYLE)
    style |= WS_EX_NOACTIVATE | WS_EX_TOOLWINDOW
    user32.SetWindowLongW(hwnd, GWL_EXSTYLE, style)
    user32.SetWindowPos(hwnd, HWND_TOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)


def reassert_topmost(hwnd):
    user32.SetWindowPos(hwnd, HWND_TOPMOST, 0, 0, 0, 0, SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE)


BG = "#181818"
MENU_BG = "#2b2b2b"
MENU_FG = "#e8e8e8"
CLOSE_RED = "#c0392b"
SIGNATURE_HOVER = "#c9a24b"
MENU_BORDER = "#1c1c1c"
ROW_HOVER = "#3f3f3f"

MIN_W, MIN_H = 78, 54
MAX_W, MAX_H = 420, 360

root = tk.Tk()
root.overrideredirect(True)
root.attributes("-topmost", True)
root.configure(bg=BG)

_start_w, _start_h = 180, 124
_sw = root.winfo_screenwidth()
_sh = root.winfo_screenheight()
_start_x = (_sw - _start_w) // 2
_start_y = (_sh - _start_h) // 2
root.geometry(f"{_start_w}x{_start_h}+{_start_x}+{_start_y}")
root.wm_minsize(MIN_W, MIN_H)
ASPECT_RATIO = _start_h / _start_w

keys_frame = tk.Frame(root, bg=BG)
keys_frame.pack(fill="both", expand=True, padx=4, pady=4)

