def _load_image(direction):
    data = base64.b64decode(_IMG_B64[direction])
    return Image.open(io.BytesIO(data)).convert("RGBA")


def _tint(img, color, amount):
    rgba = img.split()
    rgb = Image.merge("RGB", rgba[:3])
    solid = Image.new("RGB", rgb.size, color)
    blended = Image.blend(rgb, solid, amount)
    r, g, b = blended.split()
    return Image.merge("RGBA", (r, g, b, rgba[3]))


def _flatten(img, bg_color):
    flat = Image.new("RGB", img.size, bg_color)
    flat.paste(img, (0, 0), img)
    return flat


PRESS_RED = (196, 58, 48)
HOVER_GRAY = (150, 150, 150)
HOVER_AMOUNT = 0.22
PRESS_AMOUNT = 0.45
FLATTEN_BG = (24, 24, 24)

_BASE = {}
_HOVER = {}
_PRESS = {}

for _d in ("up", "left", "down", "right"):
    _raw = _load_image(_d)
    _BASE[_d] = _flatten(_raw, FLATTEN_BG)
    _HOVER[_d] = _flatten(_tint(_raw, HOVER_GRAY, HOVER_AMOUNT), FLATTEN_BG)
    _PRESS[_d] = _flatten(_tint(_raw, PRESS_RED, PRESS_AMOUNT), FLATTEN_BG)


_CACHE_MAX = 72
_RENDER_CACHE = {}


def _render(direction, mode, w, h):
    key = (direction, mode, w, h)
    hit = _RENDER_CACHE.get(key)
    if hit is not None:
        return hit
    src = _PRESS[direction] if mode == "pressed" else _HOVER[direction] if mode == "hover" else _BASE[direction]
    resized = src.resize((w, h), Image.LANCZOS)
    photo = ImageTk.PhotoImage(resized)
    if len(_RENDER_CACHE) >= _CACHE_MAX:
        _RENDER_CACHE.clear()
    _RENDER_CACHE[key] = photo
    return photo


KEY_HOLD_REPEAT_DELAY_MS = 450
KEY_HOLD_REPEAT_RATE_MS = 55


def make_button(parent, direction):
    cv = tk.Canvas(parent, bg=BG, highlightthickness=0, bd=0, cursor="arrow")
    state = {"mode": "normal", "photo": None, "pressed_key": False, "hold_job": None}

    def redraw(event=None):
        w = cv.winfo_width()
        h = cv.winfo_height()
        if w < 4 or h < 4:
            return
        mode = state["mode"]
        if state["pressed_key"]:
            mode = "pressed"
        state["photo"] = _render(direction, mode, w, h)
        cv.delete("all")
        cv.create_image(0, 0, anchor="nw", image=state["photo"])

    def set_mode(mode):
        state["mode"] = mode
        redraw()

    def cancel_hold():
        if state["hold_job"] is not None:
            root.after_cancel(state["hold_job"])
            state["hold_job"] = None

    def schedule_repeat():
        cancel_hold()
        state["hold_job"] = root.after(KEY_HOLD_REPEAT_DELAY_MS, _send_repeat)

    def _send_repeat():
        send_key(direction, key_up=False)
        state["hold_job"] = root.after(KEY_HOLD_REPEAT_RATE_MS, _send_repeat)

    def on_press(e):
        if state["pressed_key"]:
            return
        state["pressed_key"] = True
        set_mode("pressed")
        send_key(direction, key_up=False)
        schedule_repeat()

    def on_release(e):
        if not state["pressed_key"]:
            return
        state["pressed_key"] = False
        cancel_hold()
        send_key(direction, key_up=True)
        if cv.winfo_containing(e.x_root, e.y_root) is cv:
            set_mode("hover")
        else:
            set_mode("normal")

    def on_enter(e):
        if not state["pressed_key"]:
            set_mode("hover")

    def on_leave(e):
        if state["pressed_key"]:
            cancel_hold()
            send_key(direction, key_up=True)
            state["pressed_key"] = False
        set_mode("normal")

    cv.bind("<Configure>", redraw)
    cv.bind("<ButtonPress-1>", on_press)
    cv.bind("<ButtonRelease-1>", on_release)
    cv.bind("<Enter>", on_enter)
    cv.bind("<Leave>", on_leave)
    cv.bind("<ButtonPress-3>", on_right_press)
    cv.bind("<B3-Motion>", on_right_motion)
    cv.bind("<ButtonRelease-3>", on_right_release)

    return cv


_menu_font = ("Segoe UI", 9)
_sig_font = ("Segoe UI", 8, "italic")
_MENU_ROW_PAD_X = 14
_MENU_ROW_PAD_Y = 6

_active_popup = {"win": None}


def _close_popup():
    win = _active_popup["win"]
    if win is not None:
        try:
            root.unbind_all("<Button-1>")
            root.unbind_all("<Button-2>")
            root.unbind_all("<Button-3>")
        except Exception:
            pass
        try:
            win.destroy()
        except Exception:
            pass
        _active_popup["win"] = None


def _make_menu_row(parent, text, font, fg, hover_fg, hover_bg, command, center=False):
    row = tk.Frame(parent, bg=MENU_BG)
    row.pack(fill="x")
    lbl = tk.Label(
        row, text=text, font=font, bg=MENU_BG, fg=fg,
        anchor="center" if center else "w",
        padx=_MENU_ROW_PAD_X, pady=_MENU_ROW_PAD_Y,
    )
    lbl.pack(fill="x")

    def on_enter(e):
        row.configure(bg=hover_bg)
        lbl.configure(bg=hover_bg, fg=hover_fg)

    def on_leave(e):
        row.configure(bg=MENU_BG)
        lbl.configure(bg=MENU_BG, fg=fg)

    def on_click(e):
        _close_popup()
        if command:
            command()

    for w in (row, lbl):
        w.bind("<Enter>", on_enter)
        w.bind("<Leave>", on_leave)
        w.bind("<Button-1>", on_click)

    return row


def show_menu(x, y):
    _close_popup()
    win = tk.Toplevel(root)
    win.overrideredirect(True)
    win.attributes("-topmost", True)
    win.configure(bg=MENU_BORDER)
    _active_popup["win"] = win

    mf = tkfont.Font(font=_menu_font)
    sf = tkfont.Font(font=_sig_font)
    width = max(mf.measure("Grow (+)"), mf.measure("Shrink (−)"), mf.measure("Close"), sf.measure("suphimen")) + _MENU_ROW_PAD_X * 2

    inner = tk.Frame(win, bg=MENU_BG)
    inner.pack(padx=1, pady=1)
    tk.Frame(inner, bg=MENU_BG, width=width, height=1).pack()

    _make_menu_row(inner, "Grow (+)", _menu_font, MENU_FG, MENU_FG, ROW_HOVER,
                   lambda: resize_step(RESIZE_STEP_FACTOR))
    _make_menu_row(inner, "Shrink (−)", _menu_font, MENU_FG, MENU_FG, ROW_HOVER,
                   lambda: resize_step(1 / RESIZE_STEP_FACTOR))
    tk.Frame(inner, bg=MENU_BORDER, height=1).pack(fill="x")
    _make_menu_row(inner, "Close", _menu_font, MENU_FG, "white", CLOSE_RED,
                   lambda: root.destroy())
    tk.Frame(inner, bg=MENU_BORDER, height=1).pack(fill="x")
    _make_menu_row(inner, "suphimen", _sig_font, "#7a7a7a", SIGNATURE_HOVER, MENU_BG,
                   None, center=True)

    win.update_idletasks()
    sw = win.winfo_screenwidth()
    sh = win.winfo_screenheight()
    ww = win.winfo_width()
    wh = win.winfo_height()
    px = min(x, sw - ww - 4)
    py = min(y, sh - wh - 4)
    win.geometry(f"+{px}+{py}")

    def on_outside_click(event):
        w = win.winfo_containing(event.x_root, event.y_root)
        if w is None or w.winfo_toplevel() != win:
            _close_popup()

    root.bind_all("<Button-1>", on_outside_click, add="+")
    root.bind_all("<Button-2>", on_outside_click, add="+")
    root.bind_all("<Button-3>", on_outside_click, add="+")


_drag = {"active": False, "moved": False, "x": 0, "y": 0, "wx": 0, "wy": 0}


def on_right_press(event):
    _drag["active"] = True
    _drag["moved"] = False
    _drag["x"] = event.x_root
    _drag["y"] = event.y_root
    _drag["wx"] = root.winfo_x()
    _drag["wy"] = root.winfo_y()


def on_right_motion(event):
    if not _drag["active"]:
        return
    dx = event.x_root - _drag["x"]
    dy = event.y_root - _drag["y"]
    if abs(dx) > 3 or abs(dy) > 3:
        _drag["moved"] = True
    root.geometry(f"+{_drag['wx'] + dx}+{_drag['wy'] + dy}")


def on_right_release(event):
    _drag["active"] = False
    if not _drag["moved"]:
        show_menu(event.x_root, event.y_root)


RESIZE_STEP_FACTOR = 1.15

_resize_job = {"id": None}


def resize_step(factor):
    w = root.winfo_width()
    h = root.winfo_height()
    x = root.winfo_x()
    y = root.winfo_y()

    new_w = max(MIN_W, min(MAX_W, w * factor))
    new_h = max(MIN_H, min(MAX_H, new_w * ASPECT_RATIO))
    if new_h in (MIN_H, MAX_H):
        new_w = new_h / ASPECT_RATIO

    new_w_i = round(new_w)
    new_h_i = round(new_h)
    if new_w_i == w and new_h_i == h:
        return

    cx, cy = x + w / 2, y + h / 2
    new_x = round(cx - new_w_i / 2)
    new_y = round(cy - new_h_i / 2)
    root.geometry(f"{new_w_i}x{new_h_i}+{new_x}+{new_y}")
    if _resize_job["id"] is not None:
        root.after_cancel(_resize_job["id"])
    _resize_job["id"] = root.after(10, apply_window_region)


btn_up = make_button(keys_frame, "up")
btn_left = make_button(keys_frame, "left")
btn_down = make_button(keys_frame, "down")
btn_right = make_button(keys_frame, "right")

btn_up.place(relx=1 / 3, rely=0, relwidth=1 / 3, relheight=1 / 2)
btn_left.place(relx=0, rely=1 / 2, relwidth=1 / 3, relheight=1 / 2)
btn_down.place(relx=1 / 3, rely=1 / 2, relwidth=1 / 3, relheight=1 / 2)
btn_right.place(relx=2 / 3, rely=1 / 2, relwidth=1 / 3, relheight=1 / 2)

_hwnd = {}


def apply_window_region():
    hwnd = _hwnd.get("h")
    if not hwnd:
        return
    root.update_idletasks()
    rx = root.winfo_rootx()
    ry = root.winfo_rooty()
    combined = None
    for btn in (btn_up, btn_left, btn_down, btn_right):
        bw = btn.winfo_width()
        bh = btn.winfo_height()
        if bw < 2 or bh < 2:
            continue
        bx = btn.winfo_rootx() - rx
        by = btn.winfo_rooty() - ry
        radius = max(6, int(min(bw, bh) * 0.22))
        rgn = gdi32.CreateRoundRectRgn(bx, by, bx + bw, by + bh, radius, radius)
        if combined is None:
            combined = rgn
        else:
            gdi32.CombineRgn(combined, combined, rgn, RGN_OR)
            gdi32.DeleteObject(rgn)
    if combined:
        user32.SetWindowRgn(hwnd, combined, True)


def setup_window():
    root.update_idletasks()
    hwnd = user32.GetParent(root.winfo_id())
    if not hwnd:
        hwnd = root.winfo_id()
    _hwnd["h"] = hwnd
    apply_noactivate(hwnd)
    disable_shadow(hwnd)
    apply_window_region()


def keep_on_top():
    if _hwnd.get("h"):
        reassert_topmost(_hwnd["h"])
    root.after(1500, keep_on_top)


def release_mutex():
    if _mutex:
        ctypes.windll.kernel32.ReleaseMutex(_mutex)
        ctypes.windll.kernel32.CloseHandle(_mutex)


root.after(50, setup_window)
root.after(600, keep_on_top)
root.protocol("WM_DELETE_WINDOW", lambda: (release_mutex(), root.destroy()))

try:
    root.mainloop()
finally:
    release_mutex()
